-- Importación única e idempotente de PLANTULA 2026.xlsx en Mercadia Ag.
-- Fuente local: PLANTULA 2026.xlsx. El archivo no se guarda en el repositorio.
-- Se importan ventas/cobros pagados de 2025 y 2026, el libro DINERO RECIBIDO,
-- salidas con monto, semilla y nómina semanal. VENTAS A CREDITO se deja fuera:
-- dos filas no tienen precio y las otras dos duplican cobros ya asentados en el libro.
-- Los source_reference permiten re-ejecutar sin duplicar.

begin;

create temporary table _nursery_import_target (
  company_id uuid not null,
  nursery_id uuid not null
) on commit drop;

select company.id, 'Vivero', 'vivero', true
from public.companies company
where company.slug = 'mercadia-ag'
on conflict (company_id, code) do update set is_active = true, updated_at = now();

select company.id, nursery.id
from public.companies company
join public.nurseries nursery on nursery.company_id = company.id and nursery.code = 'vivero'
where company.slug = 'mercadia-ag' and nursery.is_active;

do $$
begin
  if not exists (select 1 from _nursery_import_target) then
    raise exception 'mercadia_ag_or_nursery_not_found';
  end if;
end $$;

create temporary table _nursery_import_sales (
  source_reference text primary key,
  occurred_at date not null,
  customer_name text,
  sale_kind text not null,
  payment_terms text not null,
  due_date date,
  description text not null,
  quantity numeric,
  unit text,
  unit_price numeric,
  total_amount numeric not null,
  notes text
) on commit drop;


create temporary table _nursery_import_receipts (
  source_reference text primary key,
  sale_source_reference text,
  occurred_at date not null,
  customer_name text,
  payment_method text not null,
  receipt_kind text not null,
  amount numeric not null,
  notes text
) on commit drop;


create temporary table _nursery_import_expenses (
  source_reference text primary key,
  occurred_at date not null,
  category text not null,
  amount numeric not null,
  quantity numeric,
  unit text,
  unit_price numeric,
  notes text
) on commit drop;


create temporary table _nursery_import_catalog (
  name text not null,
  unit text not null,
  default_unit_price numeric
) on commit drop;


select target.company_id, customer_name, 'Importado desde PLANTULA 2026.xlsx.'
from _nursery_import_target target
cross join (select distinct lower(trim(customer_name)) as customer_key, min(trim(customer_name)) as customer_name
            from (
              select customer_name from _nursery_import_sales where customer_name is not null
              union all
              select customer_name from _nursery_import_receipts where customer_name is not null
            ) source_customers
            group by lower(trim(customer_name))) customers
where not exists (
  select 1 from public.nursery_customers existing
  where existing.company_id = target.company_id
    and lower(trim(existing.display_name)) = customers.customer_key
);

select target.company_id, target.nursery_id, 'seedling', catalog.name, catalog.unit, catalog.default_unit_price
from _nursery_import_target target
cross join _nursery_import_catalog catalog
where not exists (
  select 1 from public.nursery_catalog_items existing
  where existing.company_id = target.company_id and existing.nursery_id = target.nursery_id
    and lower(existing.name) = lower(catalog.name)
    and lower(existing.unit) = lower(catalog.unit)
    and existing.variety is null
);

  company_id, nursery_id, customer_id, sale_kind, payment_terms, occurred_at, due_date,
  total_amount, notes, source_reference
)
select target.company_id, target.nursery_id, customer.id, source.sale_kind, source.payment_terms,
  source.occurred_at, source.due_date, round(source.total_amount, 2), source.notes, source.source_reference
from _nursery_import_target target
cross join _nursery_import_sales source
left join public.nursery_customers customer
  on customer.company_id = target.company_id and lower(trim(customer.display_name)) = lower(trim(source.customer_name))
on conflict (company_id, source_reference) where source_reference is not null do update set
  nursery_id = excluded.nursery_id, customer_id = excluded.customer_id, sale_kind = excluded.sale_kind,
  payment_terms = excluded.payment_terms, occurred_at = excluded.occurred_at, due_date = excluded.due_date,
  total_amount = excluded.total_amount, notes = excluded.notes, updated_at = now();

select target.company_id, sale.id, catalog.id, source.description, source.quantity, source.unit,
  source.unit_price, round(source.total_amount, 2)
from _nursery_import_target target
join _nursery_import_sales source on true
join public.nursery_sales sale on sale.company_id = target.company_id and sale.source_reference = source.source_reference
left join public.nursery_catalog_items catalog
  on catalog.company_id = target.company_id and catalog.nursery_id = target.nursery_id
  and lower(catalog.name) = lower(source.description) and lower(catalog.unit) = lower(coalesce(source.unit, 'pieza'))
where not exists (select 1 from public.nursery_sale_lines line where line.sale_id = sale.id);

  company_id, nursery_id, customer_id, receipt_kind, payment_method, occurred_at, amount, notes, source_reference
)
select target.company_id, target.nursery_id, customer.id, source.receipt_kind, source.payment_method,
  source.occurred_at, round(source.amount, 2), source.notes, source.source_reference
from _nursery_import_target target
cross join _nursery_import_receipts source
left join public.nursery_customers customer
  on customer.company_id = target.company_id and lower(trim(customer.display_name)) = lower(trim(source.customer_name))
on conflict (company_id, source_reference) where source_reference is not null do update set
  nursery_id = excluded.nursery_id, customer_id = excluded.customer_id, receipt_kind = excluded.receipt_kind,
  payment_method = excluded.payment_method, occurred_at = excluded.occurred_at, amount = excluded.amount,
  notes = excluded.notes, updated_at = now();

select target.company_id, receipt.id, sale.id, round(source.amount, 2)
from _nursery_import_target target
join _nursery_import_receipts source on source.sale_source_reference is not null
join public.nursery_receipts receipt on receipt.company_id = target.company_id and receipt.source_reference = source.source_reference
join public.nursery_sales sale on sale.company_id = target.company_id and sale.source_reference = source.sale_source_reference
on conflict (receipt_id, sale_id) do update set amount = excluded.amount, updated_at = now();

  company_id, nursery_id, occurred_at, category, amount, quantity, unit, unit_price,
  payment_method, notes, source_reference
)
select target.company_id, target.nursery_id, source.occurred_at, source.category, round(source.amount, 2),
  source.quantity, source.unit, source.unit_price, 'cash', source.notes, source.source_reference
from _nursery_import_target target
cross join _nursery_import_expenses source
on conflict (company_id, source_reference) where source_reference is not null do update set
  nursery_id = excluded.nursery_id, occurred_at = excluded.occurred_at, category = excluded.category,
  amount = excluded.amount, quantity = excluded.quantity, unit = excluded.unit, unit_price = excluded.unit_price,
  payment_method = excluded.payment_method, notes = excluded.notes, updated_at = now();

commit;

-- Preview counts generated from this workbook: 208 sales, 217 receipts,
-- 37 expenses and 90 customers (93 seedling catalog rows).
